 5	public final class DirectedGraph {
 6	    private final List<List<Integer>> adjacency;
 7	
 8	    private DirectedGraph(List<List<Integer>> adjacency) {
 9	        this.adjacency = adjacency;
10	    }
11	
12	    public static DirectedGraph fromEdges(int vertexCount, Edge... edges) {
13	        return fromEdges(vertexCount, List.of(edges));
14	    }
15	
16	    public static DirectedGraph fromEdges(int vertexCount, List<Edge> edges) {
17	        if (edges == null) {
18	            throw new IllegalArgumentException("Edges must not be null.");
19	        }
20	
21	        List<List<Integer>> adjacency = createEmptyAdjacency(vertexCount);
22	
23	        for (Edge edge : edges) {
24	            validateEdge(edge);
25	
26	            int from = edge.from();
27	            int to = edge.to();
28	            validateVertex(from, vertexCount);
29	            validateVertex(to, vertexCount);
30	            adjacency.get(from).add(to);
31	        }
32	
33	        return new DirectedGraph(freeze(adjacency));
34	    }
35	
36	    public int vertexCount() {
37	        return adjacency.size();
38	    }
39	
40	    public List<Integer> neighborsOf(int vertex) {
41	        validateVertex(vertex, vertexCount());
42	        return adjacency.get(vertex);
43	    }
44	
45	    public DirectedGraph reverse() {
46	        List<List<Integer>> reversedAdjacency = createEmptyAdjacency(vertexCount());
47	
48	        for (int vertex = 0; vertex < vertexCount(); vertex++) {
49	            for (int neighbor : neighborsOf(vertex)) {
50	                reversedAdjacency.get(neighbor).add(vertex);
51	            }
52	        }
53	
54	        return new DirectedGraph(freeze(reversedAdjacency));
55	    }
56	
57	    private static List<List<Integer>> createEmptyAdjacency(int vertexCount) {
58	        if (vertexCount < 0) {
59	            throw new IllegalArgumentException("Vertex count must be non-negative.");
60	        }
61	
62	        List<List<Integer>> adjacency = new ArrayList<>(vertexCount);
63	        for (int vertex = 0; vertex < vertexCount; vertex++) {
64	            adjacency.add(new ArrayList<>());
65	        }
66	        return adjacency;
67	    }
68	
69	    private static List<List<Integer>> freeze(List<List<Integer>> adjacency) {
70	        List<List<Integer>> immutableAdjacency = new ArrayList<>(adjacency.size());
71	
72	        for (List<Integer> neighbors : adjacency) {
73	            immutableAdjacency.add(List.copyOf(neighbors));
74	        }
75	
76	        return Collections.unmodifiableList(immutableAdjacency);
77	    }
78	
79	    private static void validateEdge(Edge edge) {
80	        if (edge == null) {
81	            throw new IllegalArgumentException("Edges must not contain null values.");
82	        }
83	    }
84	
85	    private static void validateVertex(int vertex, int vertexCount) {
86	        if (vertex < 0 || vertex >= vertexCount) {
87	            throw new IllegalArgumentException(
88	                "Vertex " + vertex + " is out of bounds for graph size " + vertexCount + '.'
89	            );
90	        }
91	    }
92	}

