 6	final class DepthFirstTraversal {
 7	
 8	    Deque<Integer> buildFinishingOrder(DirectedGraph graph) {
 9	        boolean[] visited = new boolean[graph.vertexCount()];
10	        Deque<Integer> finishingOrder = new ArrayDeque<>();
11	
12	        for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
13	            if (!visited[vertex]) {
14	                traverseForFinishingOrder(vertex, graph, visited, finishingOrder);
15	            }
16	        }
17	
18	        return finishingOrder;
19	    }
20	
21	    List<Integer> collectReachableVertices(int startVertex, DirectedGraph graph, boolean[] visited) {
22	        List<Integer> visitedVertices = new ArrayList<>();
23	        traverseReachableVertices(startVertex, graph, visited, visitedVertices);
24	        return visitedVertices;
25	    }
26	
27	    private void traverseForFinishingOrder(
28	        int vertex,
29	        DirectedGraph graph,
30	        boolean[] visited,
31	        Deque<Integer> finishingOrder
32	    ) {
33	        visited[vertex] = true;
34	
35	        for (int neighbor : graph.neighborsOf(vertex)) {
36	            if (!visited[neighbor]) {
37	                traverseForFinishingOrder(neighbor, graph, visited, finishingOrder);
38	            }
39	        }
40	
41	        finishingOrder.push(vertex);
42	    }
43	
44	    private void traverseReachableVertices(
45	        int vertex,
46	        DirectedGraph graph,
47	        boolean[] visited,
48	        List<Integer> visitedVertices
49	    ) {
50	        visited[vertex] = true;
51	        visitedVertices.add(vertex);
52	
53	        for (int neighbor : graph.neighborsOf(vertex)) {
54	            if (!visited[neighbor]) {
55	                traverseReachableVertices(neighbor, graph, visited, visitedVertices);
56	            }
57	        }
58	    }
59	}

